### The Minimal Web Framework

Express is a thin layer over Node's `http` module. Everything is either a **route** or **middleware**.

```js
import express from 'express';
const app = express();

// Built-in middleware
app.use(express.json());           // Parse JSON bodies
app.use(express.urlencoded({ extended: true })); // Parse form data

// Custom middleware: runs for every request
app.use((req, res, next) => {
  console.log(`${req.method} ${req.path} - ${Date.now()}`);
  next(); // Pass to the next middleware/route
});

// Route handlers
app.get('/api/users', async (req, res) => {
  const users = await db.users.findAll();
  res.json(users);
});

app.post('/api/users', async (req, res) => {
  const { name, email } = req.body;
  const user = await db.users.create({ name, email });
  res.status(201).json(user);
});

app.get('/api/users/:id', async (req, res) => {
  const user = await db.users.findById(req.params.id);
  if (!user) return res.status(404).json({ error: 'User not found' });
  res.json(user);
});

app.listen(3000);
```

#### Router Modules

```js
// routes/users.js
import { Router } from 'express';
const router = Router();

router.get('/', getUsers);
router.post('/', createUser);
router.get('/:id', getUserById);
router.put('/:id', updateUser);
router.delete('/:id', deleteUser);

export default router;

// app.js
import usersRouter from './routes/users.js';
app.use('/api/users', usersRouter);
```

